def landing():
    weekly = f'<span>{money(settings.weekly_free_credits)} in weekly promotional credits</span>' if settings.weekly_free_credits else ''
    return navigation() + f'''<main id="main" class="public-main" tabindex="-1"><section class="hero brand-hero public-hero"><div class="hero-grid" aria-hidden="true"></div><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> YOUR DRAFT. THREE AI PERSPECTIVES.</div><h1>AI text.<br><em>More natural.</em><br>More you.</h1><p>Turn a stiff first draft into clearer writing with Claude, OpenAI and Grok. Compare changes, assess AI-style signals, and export a fresh document.</p><div class="hero-cta"><a class="btn btn-mint" href="/#studio">Refine my draft <span aria-hidden="true">↗</span></a><a class="hero-link" href="/how-it-works">Meet the three models</a></div><div class="hero-meta"><span>PDF · Word · Slides · Text</span><span>From {money(settings.base_price)} / document</span></div></div><div class="draft-scene" aria-label="Illustration of the three-model editing process"><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="scene-glow"></div><div class="scene-paper paper-echo"></div><div class="scene-paper main-paper"><div class="paper-top"><span class="paper-dot"></span> YOUR NEXT CLEARER DRAFT <span>01</span></div><div class="paper-heading">Make room for<br>what matters.</div><p class="paper-copy">A little more clarity.<br>A rhythm that sounds like you.</p><div class="ink-line long"></div><div class="ink-line medium"></div><div class="ink-line short"></div><div class="paper-foot"><span>Meaning comes first</span><img src="/static/txtzi-mark.svg" alt="" width="27" height="27"></div><div class="scan-beam"></div></div><div class="model-chip chip-claude"><b>01</b><span>Claude<small>Map the meaning</small></span></div><div class="model-chip chip-openai"><b>02</b><span>OpenAI<small>Shape the wording</small></span></div><div class="model-chip chip-grok"><b>03</b><span>Grok<small>Check the source</small></span></div><span class="scene-caption">THREE-PASS PROCESS · ILLUSTRATION</span></div></section><div class="public-benefits"><span>One upfront quote</span><span>Three separate providers</span><span>Fresh document exports</span>{weekly}</div><section class="public-section"><div class="public-section-heading"><div><span class="section-eyebrow">WHY THREE MODELS?</span><h2>Different roles.<br>A more considered draft.</h2></div><p>One model maps the meaning, another writes, and a third checks the result. You can see the source and selected output together before using your document.</p></div>{model_cards()}<p class="public-fine">The roles above describe the first thorough prose rewrite. Light editing uses three editing passes. A second detector-guided revision swaps Claude and OpenAI’s roles. Multiple models can still miss an error.</p></section><section class="public-feature-grid"><article><span class="section-eyebrow">01 / WRITE</span><h2>Natural phrasing,<br>with your intent intact.</h2><p>Choose a natural, professional or conversational tone. Rewrite in English, Hebrew, Arabic, Spanish, French, German or another selected document language. The interface is currently in English.</p><a href="/how-it-works">Explore the workflow →</a></article><article><span class="section-eyebrow">02 / MEASURE</span><h2>See the signals.<br>Understand the limits.</h2><p>Optional detector comparison measures eligible English prose before and after editing. The app can retain the original when no eligible revision scores lower.</p><a href="/ai-detector-guide">Read the detector guide →</a></article><article><span class="section-eyebrow">03 / EXPORT</span><h2>A fresh document.<br>A clear account of cleanup.</h2><p>Download PDF, DOCX, PPTX or TXT. Fresh exports leave original personal metadata behind; selected invisible formatting can be cleaned. Statistical text watermarks are not assessed.</p><a href="/document-cleanup">See what is cleaned →</a></article></section><section class="public-evidence"><div><span class="section-eyebrow">OPEN RESULTS, HONEST LIMITS</span><h2>Read the actual examples.</h2><p>Compare a stored app example, ten archived trials, and a completed 1,000-variant research study. The research search is separate from the automatic app workflow; its results do not establish performance on your documents.</p></div><a class="btn btn-secondary" href="/evidence">Explore the evidence ↗</a></section>{cta()}</main>''' + footer()


def pages():
    payment = 'Card checkout is connected. You can pay for a document or buy credits when the writing services are available.' if settings.payments_ready else 'Card checkout is not available in this deployment. Existing and promotional credits can still be used when the writing services are connected.'
    weekly = f'Accounts receive {money(settings.weekly_free_credits)} in promotional credits once each ISO week, using UTC. This adds to the balance; purchased credits are not reset.' if settings.weekly_free_credits else 'Weekly promotional credits are not enabled in this deployment.'
    support = f'<h2>Contact</h2><p><a href="mailto:{esc(settings.support_email)}">{esc(settings.support_email)}</a></p>' if settings.support_email else ''
    return {
        '/about': ('About txtzi', 'A personal writing studio combining Anthropic, OpenAI and xAI for editing, source comparison and fresh document exports.', '''<p class="public-lead">txtzi helps you turn a rough or AI-assisted draft into writing you can review and make your own.</p><h2>Three providers, one visible workflow</h2><p>Anthropic, OpenAI and xAI contribute separate editorial stages. Thorough prose editing begins with a meaning outline, followed by a fresh draft and a source-fidelity review. Light editing keeps closer to your wording.</p><h2>Built for personal writing</h2><p>Upload content you own or have permission to edit. Choose your tone, get an upfront quote, and compare the selected result with your original. The personal-use declaration and provider-processing consent are required before quotation.</p><h2>Clear about what it can do</h2><p>txtzi is not a certificate of human authorship. It does not guarantee that a checker will classify your text as human, and it does not certify removal of every watermark. Its published examples describe specific tests rather than universal success rates.</p><p>txtzi is an independent application using provider APIs; the provider names describe its integrations, not an endorsement.</p><p><a href="/evidence">See the evidence and its limits →</a></p>'''),
        '/how-it-works': ('How txtzi works', 'Upload or paste, review a quote, refine with three AI providers, compare the result and download a fresh document.', '''<p class="public-lead">A clear path from rough draft to reviewed document.</p><ol class="public-steps"><li><h2>Start with your writing</h2><p>Paste text or upload PDF, DOC, DOCX, PPTX, TXT or Markdown. The limit is 20 MB, 12,000 extracted words and 100,000 extracted characters. Scanned PDF pages need OCR, when available. Select the document language, tone and editing depth.</p></li><li><h2>Review the exact price</h2><p>Accept the personal-use declaration and the notice that the three editing providers process your text. The quote itemizes length, scanned pages, slides and optional detector comparison. Pay with credits or connected card checkout, then select Generate.</p></li><li><h2>Let three models take their roles</h2><p>For eligible thorough prose, Claude maps source meaning; OpenAI drafts from the outline; Grok checks against the original. A second detector-guided revision swaps the first two roles. Light editing uses conventional editing passes. Headings, tables and slide structure have additional protection.</p></li><li><h2>Compare, review and download</h2><p>See the original and selected output, provider receipts, source-review notes and any requested detector results. Download PDF, DOCX, PPTX or TXT. These are fresh text-focused layouts; original pictures, signatures, charts and exact styling are not reproduced.</p></li></ol><h2>Language support</h2><p>Editing offers English, Hebrew, Arabic, Spanish, French, German and an Other option. The interface is English. The self-hosted detector is an English beta; selecting another document language disables detector scoring. Review language and layout quality before using exports.</p>'''),
        '/pricing': ('txtzi pricing', 'Upfront USD quotes by document length, with separate OCR, slide and optional detector fees. No recurring subscription.', f'''<p class="public-lead">One document. One clear quote. No subscription.</p><div class="public-price"><strong>{money(settings.base_price)}</strong><span>for the first 1,000 words, including all three editing providers</span></div><table class="public-table"><caption>Current prices in USD</caption><thead><tr><th scope="col">Item</th><th scope="col">Price</th></tr></thead><tbody><tr><td>Each additional started 1,000-word block</td><td>{money(settings.extra_price)}</td></tr><tr><td>Scanned-page OCR, when available</td><td>{money(settings.ocr_price)} / page</td></tr><tr><td>Presentation reconstruction</td><td>{money(settings.slide_price)} / slide</td></tr><tr><td>Optional detector comparison, per started 1,000 words</td><td>{money(settings.detector_price)}</td></tr></tbody></table><p>Detector comparison includes up to two revisions and three assessments; it does not buy a guaranteed score. Maximum document length: {settings.max_words:,} words. Quotes last one hour.</p><h2>Credits and payment availability</h2><p>100 credits equal $1.00 of service value. {esc(payment)}</p><p>{esc(weekly)}</p><h2>If processing fails</h2><p>Failed editing jobs return the document fee as credits or queue a card refund, depending on how you paid. If the optional detector cannot complete its work, its surcharge is returned as credits. Card refund completion depends on the payment provider. Review your quote before paying.</p>'''),
        '/evidence': ('txtzi evidence and research', 'Compare an app example, ten archived trials and aggregate results from 1,000 variants of one source. Research scores are separate from automatic app results.', '''<p class="public-lead">Real records. Specific examples. No invented success rate.</p><h2>What the automatic app currently does</h2><p>The live app uses a bounded editing workflow: optional detector comparison allows up to two three-provider revisions and three assessments. It may retain the original if no eligible revision scores lower. The larger research search below is not what an ordinary app job runs.</p><p>The stored live-app example shows one synthetic document, its measured versions and provider receipts. It is an example, not an accuracy benchmark or a promise about your document.</p><p><a class="btn btn-primary" href="/#demo">Compare the live-app example →</a></p><h2>Completed research: 1,000 variants of one source</h2><p class="public-fine">Phase A completed <time datetime="2026-10-04T14:05:21Z">October 4, 2026 at 14:05 UTC</time>. This is a frozen research checkpoint.</p><p>Every one of the 1,000 distinct candidate texts received full-document measurements from both pinned detectors. The selected phase A revision scored <strong>23.18 / 100 with Desklib</strong> and <strong>14.44 / 100 with Vanguard</strong>. Two separate agent reviews, blind to these scores, approved all 32 source claims and the full draft’s meaning and prose quality without editing the measured text.</p><p>Both scores were below 30. Phase A did not reach below 10 on both detectors, or below 2 on both. These numbers are uncalibrated model estimates, not percentages of AI-written words.</p><p><strong>This was not 1,000 independent three-provider rewrites.</strong> Seven shared patch banks used Claude for proposals, OpenAI for refinement and Grok for source and patch review. They used 21 completed provider requests, plus one failed attempt retained in cost accounting, to produce many distinct combinations.</p><p>All variants came from one synthetic English source. Both detectors guided adaptive selection, so neither was held out. This result does not establish performance on other writing and has not replaced the app’s automatic workflow.</p><p><a href="https://github.com/oraskdev/nonAIcheck/blob/5a46f806a9897fc04feef8305a0ae1d0342fc5c5/docs/recovery-research-results-2026-10-04.md">Read the frozen aggregate report →</a></p><p><a href="https://github.com/oraskdev/nonAIcheck/tree/5a46f806a9897fc04feef8305a0ae1d0342fc5c5/scripts/research">Inspect the public generation and scoring code →</a></p><p class="public-fine">The links above describe the method and aggregate findings. The complete source texts, provider requests, responses and recovery-study evidence are retained privately; they are not a public raw-data benchmark. Any subsequent research phase is reported separately.</p><h2>Ten archived rewrite trials</h2><p>The research record preserves ten experimental strategies on one synthetic English garden-planning document, plus separately measured source-fidelity corrections. Two fixed detectors scored the exact texts. Both detectors informed selection, so neither was a held-out evaluation.</p><p>The selected corrected research draft measured 61.61 / 100 with Desklib and 46.18 / 100 with Vanguard. These are model signals, not percentages of AI-written words. Experimental prompts and manual corrections in this record are separate from the production workflow.</p><p><a href="/static/research-ten-trials.html">View all ten trials and source reviews →</a></p><p><a href="/static/research-ten-trials.json" download>Download the archived trial data (JSON)</a></p><h2>What would stronger evidence require?</h2><p>Independent documents, a declared test procedure, source-quality reviews, multiple languages where supported, and checks that were not used to choose the rewrite. One source does not establish a general detector-pass rate.</p><h2>What is published here</h2><p>Only examples with preserved artifacts are presented as inspectable evidence. This page does not claim a below-30 or below-10 production result, universal detector avoidance, or removal of statistical watermarks.</p>'''),
        '/ai-detector-guide': ('AI detector scores explained', 'Understand txtzi’s optional AI-style assessment, English beta limits, before-and-after comparison and why scores are not authorship proof.', '''<p class="public-lead">A detector score is one signal. It is not an authorship verdict.</p><h2>What the number means here</h2><p>The selected assessment model estimates whether a passage resembles its AI-associated examples. The displayed score is not the percentage of words written by AI, and a low score does not prove a person wrote the text. Different detectors can disagree on the same document.</p><h2>How txtzi uses assessment</h2><p>When selected and available, the app compares the original with up to two eligible three-provider revisions using the detector chosen at quotation. It selects the lowest measured eligible result, which can be the original. Source and protected-value checks still apply.</p><h2>English beta</h2><p>The self-hosted option uses the Desklib model on txtzi’s server and is offered for English prose of at least 300 words, excluding presentations. Other document languages remain available for editing without this scoring option. The studio shows which detector is active; an optional GPTZero integration is used only when configured and selected.</p><h2>Use the output with context</h2><p>Review the original, changes, qualifications and source notes together. Do not treat one detector score as proof of misconduct or human authorship. No score guarantees acceptance by another checker, now or later.</p><p><a href="/evidence">Inspect the published examples →</a></p>'''),
        '/document-cleanup': ('Document cleanup and fresh exports', 'Learn which metadata and invisible formatting txtzi omits, what it preserves, and why this is not universal AI-watermark removal.', '''<p class="public-lead">A fresh file, with a precise account of what changed.</p><h2>Fresh exports</h2><p>txtzi extracts and edits text, then creates a new PDF, DOCX, PPTX or TXT file. Original author properties, comments and revision history are not copied into that export. With clean metadata enabled, creator properties are kept blank where supported; otherwise the exporter may identify txtzi.</p><h2>Selected invisible formatting</h2><p>The cleanup option removes byte-order marks (U+FEFF), soft hyphens (U+00AD) and word joiners (U+2060). The report lists formatting characters it finds. Language-specific joiners and bidirectional controls are preserved because removing them can damage writing.</p><h2>What this does not establish</h2><p>Invisible characters can occur in ordinary documents and are not proof of an AI watermark. Statistical text watermarks are not assessed. Fresh exports and formatting cleanup do not certify that every hidden marker has been found or removed.</p><h2>Layout and content limits</h2><p>Exports use a text-focused layout. Original images, charts, signatures and exact page styling are not carried over. Rights notices, citations and meaningful text are not intentionally removed. Keep your source file and review the new document before using it.</p>'''),
        '/privacy': ('txtzi privacy and data handling', 'What txtzi stores, which providers process your writing, configured content retention, deletion and essential session cookies.', f'''<p class="public-lead">Know where your writing goes.</p><h2>What is stored</h2><p>Your account includes your name, email, password hash, credit transactions and payment references. Extracted document text, revisions and reports are encrypted in the application database. Uploaded originals are processed temporarily and are not retained as original files.</p><h2>Who processes your text</h2><p>Starting generation sends relevant text to Anthropic, OpenAI and xAI. Their own data policies apply separately. The self-hosted detector runs on txtzi’s server. If GPTZero is configured instead, the studio identifies it and sends text there only when assessment is selected. A quoted document is not silently switched to a different detector.</p><h2>Retention and deletion</h2><p>Document content is scheduled for deletion after {settings.retention_hours} hours from quotation. Running or queued jobs are excluded from cleanup until processing ends. You can delete completed documents and unused quotes earlier in My documents. Infrastructure backups may retain copies until they rotate. Account, payment and accounting records are retained separately.</p><p>Deleting content here does not guarantee deletion from provider systems. Upload only material you are permitted to share with the named providers.</p><h2>Payments and cookies</h2><p>When card payments are enabled, Stripe hosts checkout; txtzi does not store your card details. An essential HTTP-only session cookie keeps you signed in. This release does not include advertising trackers.</p><h2>Your controls</h2><p>Review the processing notice before requesting a quote. Preserve your own source copy, download outputs before expiration, and use the delete control to remove active stored document content.</p>{support}<p class="public-fine">Product data-handling description updated October 4, 2026.</p>'''),
        '/terms': ('txtzi terms of use', 'Personal-use requirements, content rights, quotes, credits, refunds and the limits of AI-assisted editing and assessment.', f'''<p class="public-lead">A few clear expectations.</p><h2>Personal use and content rights</h2><p>You must own the content or have permission to edit it and share it with the processing providers. The service is for personal use. Do not use it for academic submission, impersonation, fraud, misleading authorship claims or evading an obligation to disclose AI assistance.</p><h2>What you receive</h2><p>txtzi provides AI-assisted writing refinement and fresh text-focused exports. It does not certify human authorship, guarantee a detector outcome, verify source facts or promise removal of every hidden watermark. You are responsible for reviewing the final document and its intended use.</p><h2>Quotes and credits</h2><p>Quotes are in USD and depend on extracted content and selected options. They are valid for one hour. 100 credits equal $1.00 of service value. Credits are not transferable or redeemable for cash except where required by law. There is no recurring subscription.</p><h2>Unsuccessful jobs</h2><p>If editing fails, the document fee returns to the original credit balance or is queued for a card refund. Bank processing times may vary. Optional detector fees return as credits when assessment cannot be completed. A detector score is not a promised outcome.</p><h2>Keep your own copy</h2><p>AI can introduce errors or omit details despite multiple reviews. Keep the source and download outputs you wish to retain. Document content is scheduled to expire after {settings.retention_hours} hours from quotation, subject to completion of queued or running work.</p>{support}<p class="public-fine">Product terms updated October 4, 2026.</p>'''),
    }


def metadata(path, title, description):
    url = canonical(path)
    graph = [
        {"@type": "Organization", "@id": canonical('/') + '#organization', "name": "txtzi", "url": canonical('/'), "logo": canonical('/static/txtzi-logo.svg')},
        {"@type": "WebSite", "@id": canonical('/') + '#website', "name": "txtzi", "url": canonical('/'), "inLanguage": "en"},
        {"@type": "WebPage", "@id": url, "url": url, "name": title, "description": description, "isPartOf": {"@id": canonical('/') + '#website'}, "inLanguage": "en"},
    ]
    if path == '/':
        graph.append({"@type": "SoftwareApplication", "name": "txtzi", "url": url, "applicationCategory": "ProductivityApplication", "operatingSystem": "Web browser", "description": description})
    else:
        graph.append({"@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "txtzi", "item": canonical('/')}, {"@type": "ListItem", "position": 2, "name": title, "item": url}]})
    ld = json.dumps({"@context": "https://schema.org", "@graph": graph}, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return f'<title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{esc(url)}"><meta property="og:type" content="website"><meta property="og:site_name" content="txtzi"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{esc(url)}"><meta property="og:image" content="{esc(canonical("/static/txtzi-social.png"))}"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{ld}</script>'


def asset_url(name):
    digest = hashlib.sha256((ROOT / 'static' / name).read_bytes()).hexdigest()[:12]
    return f'/static/{name}?v={digest}'


def render(path='/'):
    if path == '/':
        title = 'txtzi — AI text. More natural. More you.'
        description = 'Refine AI-assisted writing with Claude, OpenAI and Grok. Compare changes and optional AI-style assessments, then download a fresh document. Upfront quotes.'
        content = landing()
    else:
        title, description, body = pages()[path]
        content = navigation() + f'<main id="main" class="public-main" tabindex="-1"><article class="public-article"><div class="section-eyebrow">TXTZI · YOUR WORDS, REFINED</div><h1>{esc(title)}</h1>{body}</article>{cta()}</main>' + footer()
    template = (ROOT / 'static' / 'index.html').read_text()
    return (template.replace('<!--PUBLIC_METADATA-->', metadata(path, title, description))
            .replace('<!--PUBLIC_CONTENT-->', content)
            .replace('<!--APP_ATTRIBUTE-->', 'data-public-landing="true"' if path == '/' else '')
            .replace('<!--APP_SCRIPT-->', f'<script src="{asset_url("app.js")}" type="module"></script>' if path == '/' else '')
            .replace('/static/public.css', asset_url('public.css')))


def indexable_paths():
    return list(PUBLIC_PATHS) + ([RESEARCH_PATH] if (ROOT / RESEARCH_PATH.lstrip('/')).is_file() else [])


def sitemap():
    return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join(f'<url><loc>{esc(canonical(path))}</loc></url>' for path in indexable_paths()) + '</urlset>'


def robots():
    # Search crawlers can discover public content; private routes are excluded in every group.
    rules = 'Allow: /\nDisallow: /api/\nDisallow: /healthz\nDisallow: /openapi.json\nDisallow: /*?reset=\nDisallow: /*&reset=\nDisallow: /*?setup=\nDisallow: /*?checkout=\n'
    return '\n'.join('User-agent: ' + agent + '\n' + rules for agent in ('*', 'OAI-SearchBot', 'Bingbot')) + '\nSitemap: ' + canonical('/sitemap.xml') + '\n'


def research_page():
    body = (ROOT / RESEARCH_PATH.lstrip('/')).read_text()
    return body.replace('</head>', f'<link rel="canonical" href="{esc(canonical(RESEARCH_PATH))}"></head>', 1)
